package com.dropratedisplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class GroundItemTrackerTest
{
	private static final WorldPoint TILE = new WorldPoint(3200, 3200, 0);
	private static final WorldPoint OTHER = new WorldPoint(3201, 3200, 0);

	@Test
	public void tracksItemsPerTile()
	{
		GroundItemTracker t = new GroundItemTracker();
		t.add(TILE, 526, 1);   // Bones
		t.add(TILE, 995, 5);   // Coins
		t.add(OTHER, 886, 15); // Steel arrow, different tile

		assertEquals(2, t.orderedIds(TILE).size());
		assertTrue(t.orderedIds(TILE).containsAll(Arrays.asList(526, 995)));
		assertEquals(Arrays.asList(886), t.orderedIds(OTHER));
	}

	@Test
	public void sameIdSumsQuantityWithoutDuplicatingTheRow()
	{
		GroundItemTracker t = new GroundItemTracker();
		t.add(TILE, 526, 1);
		t.add(TILE, 526, 2); // second stack of the same id
		assertEquals(Arrays.asList(526), t.orderedIds(TILE));
		// Needs to remove the full summed quantity (3) before the row clears.
		t.remove(TILE, 526, 2);
		assertEquals(Arrays.asList(526), t.orderedIds(TILE));
		t.remove(TILE, 526, 1);
		assertEquals(0, t.orderedIds(TILE).size());
	}

	@Test
	public void clearEmptiesEverything()
	{
		GroundItemTracker t = new GroundItemTracker();
		t.add(TILE, 526, 1);
		t.add(OTHER, 995, 1);
		t.clear();
		assertEquals(0, t.orderedIds(TILE).size());
		assertEquals(0, t.orderedIds(OTHER).size());
	}
}

package com.dropratedisplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class InventoryDiffTest
{
	private static Map<Integer, Integer> map(int... idQtyPairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < idQtyPairs.length; i += 2)
		{
			m.put(idQtyPairs[i], idQtyPairs[i + 1]);
		}
		return m;
	}

	@Test
	public void detectsNewItem()
	{
		Map<Integer, Integer> added = InventoryDiff.added(map(995, 100), map(995, 100, 4151, 1));
		assertEquals(1, added.size());
		assertEquals(Integer.valueOf(1), added.get(4151));
	}

	@Test
	public void detectsIncreasedStack()
	{
		Map<Integer, Integer> added = InventoryDiff.added(map(4151, 1), map(4151, 3));
		assertEquals(Integer.valueOf(2), added.get(4151));
	}

	@Test
	public void ignoresRemovedItems()
	{
		Map<Integer, Integer> added = InventoryDiff.added(map(4151, 2), map(4151, 1));
		assertTrue(added.isEmpty());
	}

	@Test
	public void treatsNullBeforeAsEmpty()
	{
		Map<Integer, Integer> added = InventoryDiff.added(null, map(4151, 1));
		assertEquals(Integer.valueOf(1), added.get(4151));
	}

	@Test
	public void nullAfterYieldsEmpty()
	{
		assertTrue(InventoryDiff.added(map(4151, 1), null).isEmpty());
	}
}

package com.dropratedisplay;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.StringReader;
import org.junit.Before;
import org.junit.Test;

public class DropRateDataStoreTest
{
	private static final String JSON = "{"
		+ "\"version\":\"test\",\"sources\":{"
		+ "\"Abyssal demon\":{\"npcIds\":[415,7241],\"drops\":{\"Abyssal whip\":{\"rate\":\"1/512\",\"quantity\":\"1\"}}},"
		+ "\"Martial salvage\":{\"drops\":{\"Rune full helm\":{\"rate\":\"1/25.6\",\"quantity\":\"1\"}}},"
		// Numulite is dropped at four different quantities, each with its own rate (as real Ammonite Crabs do).
		+ "\"Ammonite Crab\":{\"drops\":{\"Numulite\":{\"rate\":\"29/128\",\"quantity\":\"4\",\"variants\":["
		+ "{\"rate\":\"8/128\",\"quantity\":\"2\"},"
		+ "{\"rate\":\"6/128\",\"quantity\":\"8\"},"
		+ "{\"rate\":\"27/175\",\"quantity\":\"5-14\"}"
		+ "]}}}"
		+ "}}";

	private DropRateDataStore store;

	@Before
	public void setUp()
	{
		store = new DropRateDataStore(new Gson());
		store.loadFromReader(new StringReader(JSON));
	}

	@Test
	public void loadsAllSources()
	{
		assertEquals(3, store.getSourceCount());
		assertEquals("test", store.getVersion());
	}

	/** The primary row's own quantity resolves to the primary rate. */
	@Test
	public void quantityLookupMatchesPrimaryRow()
	{
		DropRateEntry entry = store.getSource("Ammonite Crab").getDrop("Numulite", 4);
		assertNotNull(entry);
		assertEquals("29/128", entry.getRate());
	}

	/** A quantity carried by a variant resolves to that variant's rate, not the primary. */
	@Test
	public void quantityLookupMatchesVariantRow()
	{
		assertEquals("8/128", store.getSource("Ammonite Crab").getDrop("Numulite", 2).getRate());
		assertEquals("6/128", store.getSource("Ammonite Crab").getDrop("Numulite", 8).getRate());
	}

	/** A quantity inside a range variant resolves to that range's rate. */
	@Test
	public void quantityLookupMatchesRangeVariant()
	{
		assertEquals("27/175", store.getSource("Ammonite Crab").getDrop("Numulite", 7).getRate());
	}

	/** 8 is both an exact variant (x8) and inside a range variant (5-14); the exact row must win. */
	@Test
	public void exactQuantityBeatsOverlappingRange()
	{
		assertEquals("6/128", store.getSource("Ammonite Crab").getDrop("Numulite", 8).getRate());
	}

	/** A quantity no row lists falls back to the primary row rather than showing nothing. */
	@Test
	public void unmatchedQuantityFallsBackToPrimary()
	{
		assertEquals("29/128", store.getSource("Ammonite Crab").getDrop("Numulite", 3).getRate());
	}

	/** Items with a single quantity row return that row for any received count. */
	@Test
	public void singleRowItemIgnoresQuantity()
	{
		assertEquals("1/512", store.getSource("Abyssal demon").getDrop("Abyssal whip", 1).getRate());
		assertEquals("1/512", store.getSource("Abyssal demon").getDrop("Abyssal whip", 99).getRate());
	}

	@Test
	public void looksUpExactItemName()
	{
		DropRateEntry entry = store.lookup("Abyssal demon", "Abyssal whip");
		assertNotNull(entry);
		assertEquals("1/512", entry.getRate());
		assertEquals("Abyssal whip", entry.getItemName());
	}

	@Test
	public void looksUpItemNameCaseInsensitively()
	{
		DropRateEntry entry = store.lookup("Abyssal demon", "abyssal WHIP");
		assertNotNull(entry);
		assertEquals("1/512", entry.getRate());
	}

	@Test
	public void unknownSourceReturnsNull()
	{
		assertNull(store.getSource("Nonexistent monster"));
		assertNull(store.lookup("Nonexistent monster", "Abyssal whip"));
	}

	@Test
	public void unknownItemReturnsNull()
	{
		assertNull(store.lookup("Abyssal demon", "Dragon claws"));
	}

	@Test
	public void matchesNpcIds()
	{
		SourceDropTable table = store.getSource("Abyssal demon");
		assertNotNull(table);
		assertTrue(table.matchesNpcId(415));
		assertTrue(table.matchesNpcId(7241));
		assertFalse(table.matchesNpcId(999));
	}

	@Test
	public void salvageSourceWithoutNpcIds()
	{
		DropRateEntry entry = store.lookup("Martial salvage", "Rune full helm");
		assertNotNull(entry);
		assertEquals("1/25.6", entry.getRate());
		assertNull(store.getSource("Martial salvage").getNpcIds());
	}

	@Test
	public void bundledResourceLoadsAndIsQueryable()
	{
		DropRateDataStore bundled = new DropRateDataStore(new Gson());
		bundled.load();
		assertTrue("bundled drop_rates.json should contain many sources", bundled.getSourceCount() > 100);

		DropRateEntry whip = bundled.lookup("Abyssal demon", "Abyssal whip");
		assertNotNull("bundled data should contain Abyssal demon / Abyssal whip", whip);
		assertEquals("1/512", whip.getRate());
	}

	/**
	 * Every reward-interface / minigame source the plugin wires up must resolve (via overrides) to a real
	 * table in the bundled data. This fails the build if a source name or override drifts out of sync,
	 * rather than silently showing nothing mid-raid.
	 */
	@Test
	public void wiredRewardSourcesResolveInBundledData()
	{
		DropRateDataStore bundled = new DropRateDataStore(new Gson());
		bundled.load();

		String[] wiredSources = {
			"Barrows", "Chambers of Xeric", "Theatre of Blood", "Tombs of Amascut",
			"Lunar Chest", "Fortis Colosseum", "Fishing Trawler", "Drift Net",
			"Tempoross", "Guardians of the Rift", "Wintertodt", "Reward casket (hard)",
			"Brimstone Chest", "Crystal Chest", "Larran's big chest", "Elven Crystal Chest",
			"Chest (Ancient Vault)", "Dark Chest", "Muddy Chest",
			"Casket", "Seed pack", "Spoils of war", "Supply crate (Mahogany Homes)",
			"Herbiboar", "Unsired", "Intricate pouch", "Simple lockbox"
		};
		for (String source : wiredSources)
		{
			assertNotNull("wired source has no drop table: " + source, bundled.getSource(source));
		}

		// Spot-check that a signature unique resolves all the way through the override to a rate.
		assertNotNull("CoX Twisted bow", bundled.lookup("Chambers of Xeric", "Twisted bow"));
		assertNotNull("ToB Ghrazi rapier", bundled.lookup("Theatre of Blood", "Ghrazi rapier"));
		assertNotNull("ToA Osmumten's fang", bundled.lookup("Tombs of Amascut", "Osmumten's fang"));
		assertNotNull("Wintertodt Bruma torch", bundled.lookup("Wintertodt", "Bruma torch"));
	}
}

package com.dropratedisplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class RecentSpawnsTest
{
	private static final WorldPoint TILE_A = new WorldPoint(3200, 3200, 0);
	private static final WorldPoint TILE_B = new WorldPoint(3210, 3215, 0);

	@Test
	public void returnsTileWhenQueriedOnTheSameTick()
	{
		RecentSpawns spawns = new RecentSpawns();
		spawns.record(100, 4151, TILE_A);
		assertEquals(TILE_A, spawns.tileFor(100, 4151));
	}

	@Test
	public void returnsNullOnAdifferentTick()
	{
		RecentSpawns spawns = new RecentSpawns();
		spawns.record(100, 4151, TILE_A);
		assertNull("a spawn must not be matched to a later tick's kill", spawns.tileFor(101, 4151));
	}

	@Test
	public void recordingOnANewTickClearsTheOldTicksSpawns()
	{
		RecentSpawns spawns = new RecentSpawns();
		spawns.record(100, 4151, TILE_A);
		spawns.record(101, 526, TILE_B);
		assertNull("old tick's item is gone", spawns.tileFor(101, 4151));
		assertEquals(TILE_B, spawns.tileFor(101, 526));
	}

	@Test
	public void unknownItemReturnsNull()
	{
		RecentSpawns spawns = new RecentSpawns();
		spawns.record(100, 4151, TILE_A);
		assertNull(spawns.tileFor(100, 999));
	}

	@Test
	public void clearForgetsEverything()
	{
		RecentSpawns spawns = new RecentSpawns();
		spawns.record(100, 4151, TILE_A);
		spawns.clear();
		assertNull(spawns.tileFor(100, 4151));
	}
}

package com.dropratedisplay;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import java.awt.Color;
import org.junit.Test;

public class RarityColorTest
{
	@Test
	public void tierByDenominator()
	{
		assertEquals(RarityColor.Tier.COMMON, RarityColor.tierFor("1/2"));
		assertEquals(RarityColor.Tier.COMMON, RarityColor.tierFor("1/50"));
		assertEquals(RarityColor.Tier.UNCOMMON, RarityColor.tierFor("1/51"));
		assertEquals(RarityColor.Tier.UNCOMMON, RarityColor.tierFor("1/500"));
		assertEquals(RarityColor.Tier.RARE, RarityColor.tierFor("1/512"));
		assertEquals(RarityColor.Tier.RARE, RarityColor.tierFor("1/5000"));
		assertEquals(RarityColor.Tier.ULTRA_RARE, RarityColor.tierFor("1/6000"));
	}

	@Test
	public void tierByLabelAndAlways()
	{
		assertEquals(RarityColor.Tier.COMMON, RarityColor.tierFor("Always"));    // guaranteed = least rare
		assertEquals(RarityColor.Tier.UNCOMMON, RarityColor.tierFor("Uncommon"));
		assertEquals(RarityColor.Tier.RARE, RarityColor.tierFor("Rare"));
		assertEquals(RarityColor.Tier.ULTRA_RARE, RarityColor.tierFor("Very rare"));
		assertEquals(RarityColor.Tier.COMMON, RarityColor.tierFor(null));
	}

	@Test
	public void colourPicksTheConfiguredTier()
	{
		DropRateDisplayConfig config = mock(DropRateDisplayConfig.class);
		when(config.commonColour()).thenReturn(Color.YELLOW);
		when(config.uncommonColour()).thenReturn(Color.GREEN);
		when(config.rareColour()).thenReturn(Color.MAGENTA);
		when(config.ultraRareColour()).thenReturn(Color.RED);

		assertEquals(Color.YELLOW, RarityColor.colour("1/2", config));
		assertEquals(Color.GREEN, RarityColor.colour("1/300", config));
		assertEquals(Color.MAGENTA, RarityColor.colour("1/512", config));
		assertEquals(Color.RED, RarityColor.colour("1/9999", config));
	}
}

package com.dropratedisplay;

import com.google.gson.Gson;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.contains;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import java.io.StringReader;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Test;

public class DropRateDisplayPluginTest
{
	private static final String JSON = "{\"version\":\"test\",\"sources\":{"
		+ "\"Abyssal demon\":{\"npcIds\":[415],\"drops\":{"
		+ "\"Abyssal whip\":{\"rate\":\"1/512\",\"quantity\":\"1\"},"
		+ "\"Bones\":{\"rate\":\"Always\",\"quantity\":\"1\"},"
		+ "\"Numulite\":{\"rate\":\"29/128\",\"quantity\":\"4\",\"variants\":[{\"rate\":\"8/128\",\"quantity\":\"2\"}]}"
		+ "}},"
		+ "\"Martial salvage\":{\"drops\":{"
		+ "\"Rune full helm\":{\"rate\":\"1/25.6\",\"quantity\":\"1\"}"
		+ "}},"
		+ "\"Eclectic impling\":{\"drops\":{"
		+ "\"Rune full helm\":{\"rate\":\"1/40\",\"quantity\":\"1\"}"
		+ "}},"
		+ "\"Wall beast\":{\"drops\":{"
		+ "\"Rune full helm\":{\"rate\":\"1/32\",\"quantity\":\"1\"}"
		+ "}}}}";

	private static final int WHIP_ID = 4151;
	private static final int BONES_ID = 526;
	private static final int RUNE_FULL_HELM_ID = 1163;
	private static final int NUMULITE_ID = 21341;

	private DropRateDisplayPlugin plugin;
	private DropRateDisplayConfig config;
	private ItemManager itemManager;
	private DropRateDisplayOverlay overlay;
	private DropRateInventoryOverlay inventoryOverlay;
	private ChatMessageManager chatMessageManager;
	private Client client;

	/** RuneLite launcher: boots the client with this plugin loaded (used by the Gradle `run` task). */
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DropRateDisplayPlugin.class);
		RuneLite.main(args);
	}

	@Before
	public void setUp()
	{
		DropRateDataStore store = new DropRateDataStore(new Gson());
		store.loadFromReader(new StringReader(JSON));

		config = mock(DropRateDisplayConfig.class);
		when(config.showGroundItemRates()).thenReturn(true);
		when(config.showChatRates()).thenReturn(true);
		when(config.showInventoryRates()).thenReturn(true);
		when(config.minimumRarity()).thenReturn(10);

		itemManager = mock(ItemManager.class);
		mockItem(WHIP_ID, "Abyssal whip");
		mockItem(BONES_ID, "Bones");
		mockItem(RUNE_FULL_HELM_ID, "Rune full helm");
		mockItem(NUMULITE_ID, "Numulite");

		overlay = mock(DropRateDisplayOverlay.class);
		inventoryOverlay = mock(DropRateInventoryOverlay.class);
		chatMessageManager = mock(ChatMessageManager.class);
		client = mock(Client.class);
		when(client.getTickCount()).thenReturn(100);

		plugin = new DropRateDisplayPlugin();
		plugin.config = config;
		plugin.dataStore = store;
		plugin.itemManager = itemManager;
		plugin.overlay = overlay;
		plugin.inventoryOverlay = inventoryOverlay;
		plugin.chatMessageManager = chatMessageManager;
		plugin.client = client;
		plugin.groundItemTracker = new GroundItemTracker();
	}

	private void mockItem(int id, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(id)).thenReturn(composition);
	}

	private static NpcLootReceived npcLoot(String npcName, ItemStack... items)
	{
		NPC npc = mock(NPC.class);
		when(npc.getName()).thenReturn(npcName);
		when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		return new NpcLootReceived(npc, java.util.Arrays.asList(items));
	}

	private static Map<Integer, Integer> itemMap(int id, int quantity)
	{
		Map<Integer, Integer> map = new HashMap<>();
		map.put(id, quantity);
		return map;
	}

	@Test
	public void npcDropRendersRateOnGround()
	{
		// No spawn recorded this tick, so the rate falls back to the NPC's own tile (the common case).
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(WHIP_ID, 1)));
		verify(overlay).addGroundRate(eq(new WorldPoint(3200, 3200, 0)), eq(WHIP_ID), eq("Abyssal whip"), contains("1/512"));
	}

	/**
	 * Many bosses (the Leviathan, the Wilderness trio, …) drop loot under the player, not on the NPC's tile,
	 * and NpcLootReceived carries no location. The rate must anchor to where the item actually spawned.
	 */
	@Test
	public void bossLootAnchorsToSpawnTileNotNpcTile()
	{
		WorldPoint underPlayer = new WorldPoint(3210, 3215, 0);
		plugin.recentSpawns.record(100, WHIP_ID, underPlayer); // the whip spawned here this tick (tick 100)
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(WHIP_ID, 1))); // NPC is at (3200, 3200)
		verify(overlay).addGroundRate(eq(underPlayer), eq(WHIP_ID), eq("Abyssal whip"), contains("1/512"));
	}

	/** A multi-quantity drop shows the rate for the exact stack received: x4 resolves to the primary row. */
	@Test
	public void multiQuantityDropUsesRateForItsQuantity()
	{
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(NUMULITE_ID, 4)));
		verify(overlay).addGroundRate(any(), eq(NUMULITE_ID), eq("Numulite"), eq("29/128"));
	}

	/** The same item at a different quantity shows the variant's rate, not the primary: x2 -> 8/128. */
	@Test
	public void multiQuantityDropUsesVariantRateForOtherQuantity()
	{
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(NUMULITE_ID, 2)));
		verify(overlay).addGroundRate(any(), eq(NUMULITE_ID), eq("Numulite"), eq("8/128"));
	}

	/**
	 * Every rated drop is passed to the overlay with its raw rate. The rarity filter (minimum rarity,
	 * "hide guaranteed drops", qualitative) is applied live at render time, so it is not gated here.
	 */
	@Test
	public void ratedDropIsPassedRawToOverlay()
	{
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(BONES_ID, 1)));
		verify(overlay).addGroundRate(any(), eq(BONES_ID), eq("Bones"), eq("Always"));
	}

	@Test
	public void unknownSourceIsIgnored()
	{
		plugin.onNpcLootReceived(npcLoot("Cave goblin", new ItemStack(WHIP_ID, 1)));
		verify(overlay, never()).addGroundRate(any(), anyInt(), any(), any());
	}

	@Test
	public void groundOverlayDisabledSuppressesOutput()
	{
		when(config.showGroundItemRates()).thenReturn(false);
		plugin.onNpcLootReceived(npcLoot("Abyssal demon", new ItemStack(WHIP_ID, 1)));
		verify(overlay, never()).addGroundRate(any(), anyInt(), any(), any());
	}

	/** Salvage where the trigger arrives before the inventory change: must emit chat + inventory rate. */
	@Test
	public void salvageTriggerThenItemProducesChatAndInventoryRate()
	{
		plugin.beginPending("Martial salvage");
		plugin.handleInventoryChange(itemMap(RUNE_FULL_HELM_ID, 1));

		verify(chatMessageManager).queue(any());
		// Inventory icon gets the raw rate; the overlay formats it live (rounds 1/25.6 -> 1/26 on the icon).
		verify(inventoryOverlay).addRate(eq(RUNE_FULL_HELM_ID), eq("1/25.6"));
	}

	/** The ordering that broke the old snapshot-at-trigger code: item arrives before the trigger. */
	@Test
	public void salvageItemThenTriggerStillPairs()
	{
		plugin.handleInventoryChange(itemMap(RUNE_FULL_HELM_ID, 1));
		plugin.beginPending("Martial salvage");

		verify(inventoryOverlay).addRate(eq(RUNE_FULL_HELM_ID), eq("1/25.6"));
	}

	/** An inventory change with no matching source trigger must not emit anything. */
	@Test
	public void inventoryChangeWithoutTriggerIsSilent()
	{
		plugin.handleInventoryChange(itemMap(RUNE_FULL_HELM_ID, 1));

		verify(chatMessageManager, never()).queue(any());
		verify(inventoryOverlay, never()).addRate(anyInt(), any());
	}

	/** Impling loot arrives via ServerNpcLoot (knapsack), never the ground: show chat + inventory rate. */
	@Test
	public void implingServerLootShowsChatAndInventoryRate()
	{
		plugin.handleServerNpcLoot("Eclectic impling", itemMap(RUNE_FULL_HELM_ID, 1));

		verify(chatMessageManager).queue(any());
		verify(inventoryOverlay).addRate(eq(RUNE_FULL_HELM_ID), eq("1/40"));
	}

	/** Wall beasts retreat into the wall, so they never fire NpcLootReceived; loot comes via ServerNpcLoot. */
	@Test
	public void wallBeastServerLootShowsChatAndInventoryRate()
	{
		plugin.handleServerNpcLoot("Wall beast", itemMap(RUNE_FULL_HELM_ID, 1));

		verify(chatMessageManager).queue(any());
		verify(inventoryOverlay).addRate(eq(RUNE_FULL_HELM_ID), eq("1/32"));
	}

	/** Ordinary kills also fire ServerNpcLoot but are shown on the ground; only implings route here. */
	@Test
	public void nonImplingServerLootIsIgnored()
	{
		plugin.handleServerNpcLoot("Abyssal demon", itemMap(WHIP_ID, 1));

		verify(chatMessageManager, never()).queue(any());
		verify(inventoryOverlay, never()).addRate(anyInt(), any());
	}
}

package com.dropratedisplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RateParserTest
{
	private static final double DELTA = 0.001;

	@Test
	public void parsesSimpleFraction()
	{
		assertEquals(512.0, RateParser.parseDenominator("1/512"), DELTA);
	}

	@Test
	public void parsesMultiNumeratorFraction()
	{
		assertEquals(128.0 / 3.0, RateParser.parseDenominator("3/128"), DELTA);
	}

	@Test
	public void parsesDecimalDenominator()
	{
		assertEquals(25.6, RateParser.parseDenominator("1/25.6"), DELTA);
	}

	@Test
	public void alwaysIsNegativeOne()
	{
		assertEquals(-1.0, RateParser.parseDenominator("Always"), DELTA);
		assertEquals(-1.0, RateParser.parseDenominator("1/1"), DELTA);
	}

	@Test
	public void qualitativeAndBlankAreZero()
	{
		assertEquals(0.0, RateParser.parseDenominator("Uncommon"), DELTA);
		assertEquals(0.0, RateParser.parseDenominator(""), DELTA);
		assertEquals(0.0, RateParser.parseDenominator(null), DELTA);
	}

	@Test
	public void ignoresFootnoteWhenParsing()
	{
		assertEquals(128.0, RateParser.parseDenominator("1/128 (with ring of wealth)"), DELTA);
	}

	@Test
	public void handlesThousandsSeparatorCommas()
	{
		assertEquals(2448.0, RateParser.parseDenominator("1/2,448"), DELTA);
		assertEquals("1/2,448", RateParser.formatRate("1/2,448"));
		assertTrue(RateParser.isRareEnough("1/2,448", 100));
	}

	@Test
	public void isAlwaysMatchesGuaranteedDrops()
	{
		assertTrue(RateParser.isAlways("Always"));
		assertTrue(RateParser.isAlways("1/1"));
		assertFalse(RateParser.isAlways("1/512"));
	}

	@Test
	public void isQualitativeMatchesLabels()
	{
		assertTrue(RateParser.isQualitative("Rare"));
		assertTrue(RateParser.isQualitative("very rare"));
		assertFalse(RateParser.isQualitative("1/512"));
	}

	@Test
	public void isRareEnoughRespectsThreshold()
	{
		assertTrue(RateParser.isRareEnough("1/512", 10));
		assertFalse(RateParser.isRareEnough("1/5", 10));
		assertFalse(RateParser.isRareEnough("Always", 10));
		assertFalse(RateParser.isRareEnough("Common", 10));
		assertTrue(RateParser.isRareEnough("1/5", 0));
	}

	@Test
	public void shouldDisplayAppliesEveryFilter()
	{
		// Numeric rates are gated purely by the minimum-rarity threshold.
		assertTrue(RateParser.shouldDisplay("1/512", 10, false, false));
		assertFalse(RateParser.shouldDisplay("1/5", 10, false, false));
		assertTrue(RateParser.shouldDisplay("1/5", 0, false, false));      // 0 = show everything

		// Guaranteed drops only show when explicitly enabled.
		assertFalse(RateParser.shouldDisplay("Always", 0, false, false));
		assertTrue(RateParser.shouldDisplay("Always", 0, false, true));

		// Qualitative labels only show when explicitly enabled.
		assertFalse(RateParser.shouldDisplay("Rare", 0, false, false));
		assertTrue(RateParser.shouldDisplay("Rare", 0, true, false));

		assertFalse(RateParser.shouldDisplay(null, 0, true, true));
	}

	@Test
	public void formatStripsFootnoteAndKeepsLabels()
	{
		assertEquals("1/512", RateParser.formatRate("1/512"));
		assertEquals("1/128", RateParser.formatRate("1/128 (with ring of wealth)"));
		assertEquals("1/50", RateParser.formatRate("  1/50  "));
		assertEquals("Rare", RateParser.formatRate("Rare"));
	}

	@Test
	public void formatRoundsToWholeOneInN()
	{
		assertEquals("1/24", RateParser.formatRate("100/2,440"));
		assertEquals("1/8", RateParser.formatRate("300/2440"));
		assertEquals("1/43", RateParser.formatRate("3/128"));
		assertEquals("1/512", RateParser.formatRate("1/512"));
		assertEquals("1/26", RateParser.formatRate("1/25.6"));
		assertEquals("Always", RateParser.formatRate("Always"));
	}

	@Test
	public void formatFullKeepsWikiFraction()
	{
		assertEquals("100/2,440", RateParser.formatRateFull("100/2,440"));
		assertEquals("3/128", RateParser.formatRateFull("3/128"));
		assertEquals("1/512", RateParser.formatRateFull("1/512"));
		assertEquals("Always", RateParser.formatRateFull("Always"));
		assertEquals("Rare", RateParser.formatRateFull("Rare"));
	}

	@Test
	public void formatDispatchesByRateFormat()
	{
		assertEquals("100/2,440", RateParser.format("100/2,440", RateFormat.EXACT));
		assertEquals("1/24.4", RateParser.format("100/2,440", RateFormat.ONE_IN_X));
		assertEquals("1/24", RateParser.format("100/2,440", RateFormat.ONE_IN_X_ROUNDED));
		assertEquals("1/512", RateParser.format("1/512", RateFormat.ONE_IN_X)); // whole -> no ".0"
		assertEquals("Always", RateParser.format("Always", RateFormat.ONE_IN_X));
	}
}

package com.dropratedisplay;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled {@code drop_rates.json} resource and answers drop-rate lookups.
 *
 * <p>The data is keyed by source name (matching an NPC name, salvage tier, casket name, etc.) and
 * then by item name within each source. A small override map translates the handful of loot event
 * names that do not match their wiki page title.
 */
@Slf4j
@Singleton
public class DropRateDataStore
{
	private static final String RESOURCE = "/drop_rates.json";

	/**
	 * Loot-event source names that differ from the wiki page name the data is keyed by.
	 * Most sources match exactly; add entries here as mismatches are discovered through testing.
	 */
	private static final Map<String, String> SOURCE_NAME_OVERRIDES = new HashMap<>();

	static
	{
		// Activity/interface names (what the plugin derives from the reward interface or region) mapped to
		// the wiki page the drop data actually lives on. Clue caskets need no entry: the derived
		// "Reward casket (tier)" already matches the wiki page name. Verified against the bundled data.
		SOURCE_NAME_OVERRIDES.put("Barrows", "Chest (Barrows)");
		SOURCE_NAME_OVERRIDES.put("Chambers of Xeric", "Ancient chest");
		SOURCE_NAME_OVERRIDES.put("Theatre of Blood", "Monumental chest");
		SOURCE_NAME_OVERRIDES.put("Tombs of Amascut", "Chest (Tombs of Amascut)");
		SOURCE_NAME_OVERRIDES.put("Fortis Colosseum", "Rewards Chest (Fortis Colosseum)");
		SOURCE_NAME_OVERRIDES.put("Drift Net", "Drift net fishing");
		SOURCE_NAME_OVERRIDES.put("Tempoross", "Reward pool");
		SOURCE_NAME_OVERRIDES.put("Wintertodt", "Reward Cart");
		SOURCE_NAME_OVERRIDES.put("Guardians of the Rift", "Rewards Guardian");
	}

	private final Gson gson;

	private Map<String, SourceDropTable> sources = Collections.emptyMap();
	private Map<String, SourceDropTable> lowerCaseSources = Collections.emptyMap();

	@Getter
	private String version = "unknown";

	@Inject
	DropRateDataStore(Gson gson)
	{
		this.gson = gson;
	}

	/** Loads the bundled data file from the classpath. Safe to call again to reload. */
	public void load()
	{
		try (InputStream is = DropRateDataStore.class.getResourceAsStream(RESOURCE))
		{
			if (is == null)
			{
				log.warn("drop_rates.json not found on the classpath; drop rate lookups will be empty");
				return;
			}

			try (Reader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				loadFromReader(reader);
				log.debug("Loaded drop rate data version {} with {} sources", version, sources.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to load drop rate data", e);
		}
	}

	/** Package-private hook so tests can load data without a classpath resource. */
	void loadFromReader(Reader reader)
	{
		DropRateData data = gson.fromJson(reader, DropRateData.class);
		if (data == null || data.sources == null)
		{
			return;
		}

		Map<String, SourceDropTable> lower = new HashMap<>();
		for (Map.Entry<String, SourceDropTable> entry : data.sources.entrySet())
		{
			SourceDropTable table = entry.getValue();
			if (table != null)
			{
				table.setSourceName(entry.getKey());
				table.index();
				lower.putIfAbsent(entry.getKey().toLowerCase(Locale.ROOT), table);
			}
		}

		this.sources = data.sources;
		this.lowerCaseSources = lower;
		this.version = data.version != null ? data.version : "unknown";
	}

	/**
	 * Resolves a loot-event source name to its drop table, applying name overrides and stripping any
	 * {@code #variant} anchor as a fallback.
	 */
	public SourceDropTable getSource(String sourceName)
	{
		if (sourceName == null)
		{
			return null;
		}

		String key = SOURCE_NAME_OVERRIDES.getOrDefault(sourceName, sourceName);
		SourceDropTable table = lookupKey(key);

		if (table == null)
		{
			int hash = key.indexOf('#');
			if (hash > 0)
			{
				table = lookupKey(key.substring(0, hash));
			}
		}
		return table;
	}

	/** Exact match first, then case-insensitive (chat gives lowercase source names like "man" / "martial"). */
	private SourceDropTable lookupKey(String key)
	{
		SourceDropTable table = sources.get(key);
		if (table == null)
		{
			table = lowerCaseSources.get(key.toLowerCase(Locale.ROOT));
		}
		return table;
	}

	/** Convenience: look up a single item's drop entry for a source. */
	public DropRateEntry lookup(String sourceName, String itemName)
	{
		SourceDropTable table = getSource(sourceName);
		return table == null ? null : table.getDrop(itemName);
	}

	public int getSourceCount()
	{
		return sources.size();
	}

	/** Top-level shape of {@code drop_rates.json}. */
	private static class DropRateData
	{
		private String version;
		private Map<String, SourceDropTable> sources;
	}
}

