		CHEST_REGIONS.put(13151, "Elven Crystal Chest");
		CHEST_REGIONS.put(5277, "Stone chest");
		CHEST_REGIONS.put(10835, "Dorgesh-Kaan Chest");
		CHEST_REGIONS.put(10834, "Dorgesh-Kaan Chest");
		CHEST_REGIONS.put(7323, "Grubby Chest");
		CHEST_REGIONS.put(8593, "Isle of Souls Chest");
		CHEST_REGIONS.put(7827, "Dark Chest");
		CHEST_REGIONS.put(13117, "Rogues' Chest");
		CHEST_REGIONS.put(13156, "Chest (Ancient Vault)");
		CHEST_REGIONS.put(12348, "Muddy Chest");
		CHEST_REGIONS.put(5422, "Chest (Aldarin Villas)");
		CHEST_REGIONS.put(6550, "Chest (Moon key)");
		CHEST_REGIONS.put(5521, "Chest (Alchemist's signet)");
		CHEST_REGIONS.put(12073, "Rusty chest");
		CHEST_REGIONS.put(7470, "Rusty chest");
		CHEST_REGIONS.put(6187, "Tarnished chest");
		CHEST_REGIONS.put(6953, "Tarnished chest");
		CHEST_REGIONS.put(7743, "Reinforced chest");
		CHEST_REGIONS.put(8758, "Reinforced chest");
	}

	@Inject
	Client client;

	@Inject
	DropRateDisplayConfig config;

	@Inject
	DropRateDataStore dataStore;

	@Inject
	ItemManager itemManager;

	@Inject
	DropRateDisplayOverlay overlay;

	@Inject
	DropRateInventoryOverlay inventoryOverlay;

	@Inject
	RewardInterfaceOverlay rewardOverlay;

	@Inject
	GroundItemTracker groundItemTracker;

	@Inject
	ChatMessageManager chatMessageManager;

	@Inject
	private OverlayManager overlayManager;

	// Non-NPC loot detection: a rolling inventory snapshot is kept up to date, and a trigger
	// (chat message or reward widget) names the source. When both a source and a fresh set of added
	// items exist within MATCH_WINDOW_TICKS, they are paired -- order-independent.
	private Map<Integer, Integer> inventorySnapshot = new HashMap<>();
	private Map<Integer, Integer> recentAdded;
	private int recentAddedTick = Integer.MIN_VALUE;
	private String pendingSource;
	private int pendingTick = Integer.MIN_VALUE;

	// Where each item spawned this tick, so a floor drop is anchored to where the loot actually landed
	// rather than the NPC's tile (many bosses drop under the player). Package-private for tests.
	RecentSpawns recentSpawns = new RecentSpawns();

	@Provides
	DropRateDisplayConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropRateDisplayConfig.class);
	}

	@Override
	protected void startUp()
	{
		dataStore.load();
		overlayManager.add(overlay);
		overlayManager.add(inventoryOverlay);
		overlayManager.add(rewardOverlay);
		resetState();
		log.debug("Drop Rate Display started ({} sources)", dataStore.getSourceCount());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(inventoryOverlay);
		overlayManager.remove(rewardOverlay);
		overlay.clear();
		inventoryOverlay.clear();
		resetState();
	}

	// --- Monster kills: floor drops rendered on the ground -----------------------------------------

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (!config.showGroundItemRates())
		{
			return;
		}

		NPC npc = event.getNpc();
		if (npc == null)
		{
			return;
		}

		SourceDropTable table = dataStore.getSource(npc.getName());
		if (table == null)
		{
			return;
		}

		WorldPoint location = npc.getWorldLocation();
		if (location == null)
		{
			return;
		}

		for (ItemStack item : event.getItems())
		{
			String itemName = itemManager.getItemComposition(item.getId()).getName();
			DropRateEntry entry = table.getDrop(itemName, item.getQuantity());
			if (entry == null)
			{
				continue;
			}

			// Store the raw wiki rate; the overlay applies the format, rarity filter and colour each frame,
			// so changing any of those settings updates what is already on screen. Anchor to where the item
			// actually spawned this tick (bosses like the Leviathan drop under the player, not on their tile).
			overlay.addGroundRate(dropTileFor(item.getId(), location), item.getId(), itemName, entry.getRate());
		}
	}

	/**
	 * The tile to anchor a floor rate on. {@link NpcLootReceived} carries no location, and many bosses
	 * (the Leviathan, the Wilderness trio, Vorkath, Nex, …) drop loot under the player rather than on the
	 * NPC's tile. RuneLite's LootManager gathers the loot from wherever it spawned this tick, so we mirror
	 * that: use the tile the item was seen spawning on this tick, falling back to the NPC's own tile when we
	 * didn't see it spawn (e.g. loot that goes straight to the inventory).
	 */
	private WorldPoint dropTileFor(int itemId, WorldPoint npcLocation)
	{
		final WorldPoint spawned = recentSpawns.tileFor(client.getTickCount(), itemId);
		return spawned != null ? spawned : npcLocation;
	}

	/**
	 * Server-reported loot that never lands on the ground. Implings deliver their loot straight to the
	 * inventory -- whether caught with a net, caught barehanded, or collected by looting an impling jar --
	 * and are reported here, not via {@link NpcLootReceived}. Only implings are routed to the inventory/chat
	 * display: ordinary kills also fire this event, but their loot is on the ground and already shown by
	 * {@link #onNpcLootReceived}, so handling them here as well would show every drop twice.
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		Map<Integer, Integer> items = new HashMap<>();
		for (ItemStack item : event.getItems())
		{
			items.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
		handleServerNpcLoot(Text.removeTags(event.getComposition().getName()), items);
	}

	/**
	 * Sources whose loot the server reports via {@link ServerNpcLoot} but that never fire
	 * {@link NpcLootReceived}, because they don't die a normal death on a tile: implings are caught, and
	 * wall beasts retreat into the wall. We show these in chat + on the item icon (there's no ground
	 * location to place them on). Ordinary kills DO fire {@link NpcLootReceived} and are shown on the floor,
	 * so they must not be routed here or every drop would show twice.
	 */
	private static boolean isServerLootSource(String npcName)
	{
		final String lower = npcName.toLowerCase(Locale.ROOT);
		return lower.contains("impling") || lower.equals("wall beast");
	}

	/** Core of {@link #onServerNpcLoot}, split out so it can be driven directly in tests. */
	void handleServerNpcLoot(String npcName, Map<Integer, Integer> items)
	{
		if (npcName == null || !isServerLootSource(npcName))
		{
			return;
		}
		processInventoryLoot(npcName, items);
	}

	// --- Ground Items row-order mirror: feed the tracker the same spawns/despawns it sees, so our merged
	//     rates sit on the exact rows it draws (see GroundItemTracker). -----------------------------------

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		final WorldPoint tile = event.getTile().getWorldLocation();
		final int itemId = event.getItem().getId();
		groundItemTracker.add(tile, itemId, event.getItem().getQuantity());
		// NpcLootReceived carries no location; remember where each item spawned this tick so a boss drop
		// that lands under the player is anchored there rather than on the NPC's tile.
		recentSpawns.record(client.getTickCount(), itemId, tile);
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		final WorldPoint tile = event.getTile().getWorldLocation();
		final int itemId = event.getItem().getId();
		groundItemTracker.remove(tile, itemId, event.getItem().getQuantity());
		// Once the item is fully gone from the tile, drop its ground rate. There is no 30s timer for floor
		// drops: the rate lives exactly as long as the item is on the ground.
		if (!groundItemTracker.contains(tile, itemId))
		{
			overlay.removeGroundRate(tile, itemId);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			groundItemTracker.clear();
		}
	}

	// --- Non-NPC loot: chat/widget triggers paired with the inventory change -----------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
		{
			return;
		}

		String message = event.getMessage();

		// Remember the most recently completed clue tier so we can name the reward casket source.
		Matcher clue = CLUE_COMPLETED_PATTERN.matcher(message);
		if (clue.find())
		{
			// The clue reward screen reuses one interface across tiers; tell the overlay which casket so
			// it can draw the right table when the reward interface opens.
			rewardOverlay.setClueCasketSource("Reward casket (" + clue.group(1) + ")");
			return;
		}

		if (message.equals(HERBIBOAR_MESSAGE))
		{
			beginPending("Herbiboar");
			return;
		}
		if (message.equals(UNSIRED_MESSAGE))
		{
			beginPending("Unsired");
			return;
		}

		Matcher pickpocket = PICKPOCKET_PATTERN.matcher(message);
		if (pickpocket.matches())
		{
			String source = Text.removeTags(pickpocket.group("target"));
			log.debug("[Drop Rate] pickpocket trigger -> '{}'", source);
			beginPending(source);
			return;
		}

		Matcher salvage = SALVAGE_PATTERN.matcher(message);
		if (salvage.matches())
		{
			String source = Text.removeTags(salvage.group("tier")) + " salvage";
			log.debug("[Drop Rate] salvage trigger -> '{}'", source);
			beginPending(source);
			return;
		}

		// Skilling minigames (Tempoross / Guardians of the Rift / Wintertodt) announce loot with a common
		// message then deposit it to the inventory; the region tells us which activity it is.
		if (message.contains(FOUND_LOOT_MESSAGE))
		{
			String source = minigameSourceForRegion();
			if (source != null)
			{
				log.debug("[Drop Rate] minigame loot trigger -> '{}'", source);
				beginPending(source);
			}
			return;
		}

		// World chests: the region identifies which chest was looted; the loot lands in the inventory.
		if (isChestLootMessage(message))
		{
			String source = CHEST_REGIONS.get(playerRegion());
			if (source != null)
			{
				log.debug("[Drop Rate] chest trigger -> '{}'", source);
				beginPending(source);
			}
		}
	}

	private static boolean isChestLootMessage(String message)
	{
		return message.equals("You find some treasure in the chest!")
			|| message.equals("You steal some loot from the chest.")
			|| message.equals("You find treasure inside!")
			|| message.equals("You take some loot from inside.")
			|| message.startsWith("You open the chest and find")
			|| GRUBBY_CHEST_PATTERN.matcher(message).matches();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!event.isItemOp())
		{
			return;
		}

		String option = event.getMenuOption();
		if (!option.equals("Open") && !option.equals("Search") && !option.equals("Take") && !option.equals("Take-all"))
		{
			return;
		}

		// Opening a loot container deposits its contents to the inventory. Name the source after the item
		// (overridden where the wiki page differs), then let the inventory diff + data lookup self-filter:
		// non-loot items simply resolve to no drop table and show nothing.
		int itemId = event.getItemId();
		String source = OPENED_ITEM_SOURCES.get(itemId);
		if (source == null)
		{
			source = itemManager.getItemComposition(itemId).getName();
		}
		beginPending(source);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		handleInventoryChange(toItemMap(event.getItemContainer()));
	}

	/** Core inventory-diff step, split out from the event handler so it can be driven directly in tests. */
	void handleInventoryChange(Map<Integer, Integer> current)
	{
		Map<Integer, Integer> added = InventoryDiff.added(inventorySnapshot, current);
		inventorySnapshot = current;

		if (!added.isEmpty())
		{
			recentAdded = added;
			recentAddedTick = client.getTickCount();
		}

		tryMatch();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		if (pendingSource != null && tick - pendingTick > MATCH_WINDOW_TICKS)
		{
			pendingSource = null;
		}
		if (recentAdded != null && tick - recentAddedTick > MATCH_WINDOW_TICKS)
		{
			recentAdded = null;
		}
	}

	void beginPending(String source)
	{
		if (!config.showChatRates() && !config.showInventoryRates())
		{
			return;
		}

		pendingSource = source;
		pendingTick = client.getTickCount();
		tryMatch();
	}

	/** Pairs a pending source with recently added items when both are present within the match window. */
	private void tryMatch()
	{
		if (pendingSource == null || recentAdded == null)
		{
			return;
		}
		if (Math.abs(pendingTick - recentAddedTick) > MATCH_WINDOW_TICKS)
		{
			return;
		}

		String source = pendingSource;
		Map<Integer, Integer> added = recentAdded;
		pendingSource = null;
		recentAdded = null;
		processInventoryLoot(source, added);
	}

	private void processInventoryLoot(String source, Map<Integer, Integer> added)
	{
		SourceDropTable table = dataStore.getSource(source);
		if (table == null)
		{
			log.debug("[Drop Rate] no drop table for inventory source '{}'", source);
			return;
		}

		String displaySource = table.getSourceName() != null ? table.getSourceName() : source;

		for (Map.Entry<Integer, Integer> addedItem : added.entrySet())
		{
			int itemId = addedItem.getKey();
			int quantity = addedItem.getValue();
			String itemName = itemManager.getItemComposition(itemId).getName();
			DropRateEntry entry = table.getDrop(itemName, quantity);
			if (entry == null)
			{
				continue;
			}

			// Chat is one-shot, so it is filtered and formatted now. The inventory icon stores the raw
			// rate and lets the overlay filter / format / colour it live.
			if (config.showChatRates() && shouldDisplay(entry.getRate()))
			{
				sendChatMessage(itemName, displaySource, RateParser.format(entry.getRate(), config.chatRateFormat()));
			}
			if (config.showInventoryRates())
			{
				inventoryOverlay.addRate(itemId, entry.getRate());
			}
		}
	}

	private String minigameSourceForRegion()
	{
		int region = playerRegion();
		if (region == TEMPOROSS_REGION)
		{
			return "Tempoross";
		}
		if (region == GUARDIANS_OF_THE_RIFT_REGION)
		{
			return "Guardians of the Rift";
		}
		if (region == WINTERTODT_REGION)
		{
			return "Wintertodt";
		}
		return null;
	}

	private int playerRegion()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return -1;
		}
		return player.getWorldLocation().getRegionID();
	}

	// --- Shared helpers ----------------------------------------------------------------------------

	private boolean shouldDisplay(String rate)
	{
		return RateParser.shouldDisplay(rate, config.minimumRarity(), config.showQualitativeRates(),
			config.showGuaranteedDrops());
	}

	private void sendChatMessage(String itemName, String source, String rate)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Drop Rate] ")
			.append(ChatColorType.NORMAL)
			.append(itemName)
			.append(" from ")
			.append(source)
			.append(": ")
			.append(ChatColorType.HIGHLIGHT)
			.append(rate)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private static Map<Integer, Integer> toItemMap(ItemContainer container)
	{
		Map<Integer, Integer> map = new HashMap<>();
		if (container == null)
		{
			return map;
		}

		for (Item item : container.getItems())
		{
			if (item.getId() >= 0)
			{
				map.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return map;
	}

	private void resetState()
	{
		pendingSource = null;
		recentAdded = null;
		inventorySnapshot = new HashMap<>();
		rewardOverlay.setClueCasketSource(null);
		recentSpawns.clear();
	}
}

package com.dropratedisplay;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parsing and formatting helpers for wiki drop-rate strings.
 *
 * <p>Wiki rates come in several shapes: fractional ({@code 1/512}, {@code 3/128}), decimal fractional
 * ({@code 1/25.6}), {@code Always}/{@code 1/1}, qualitative labels ({@code Common}, {@code Rare}...),
 * and fractions with trailing footnotes ({@code "1/128 (with ring of wealth)"}). These helpers extract
 * the leading fraction and ignore any footnote text.
 */
public final class RateParser
{
	/**
	 * Matches the first {@code numerator/denominator} fraction anywhere in the string. Each number may
	 * use thousands-separator commas ({@code 2,448}) and a decimal part ({@code 25.6}); commas are only
	 * allowed in proper 3-digit groups so trailing punctuation is not swallowed.
	 */
	private static final Pattern FRACTION = Pattern.compile(
		"(\\d+(?:,\\d{3})*(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:,\\d{3})*(?:\\.\\d+)?)");

	private RateParser()
	{
	}

	/**
	 * Parses a rate string to its effective "1 in X" denominator for comparison.
	 *
	 * @return the denominator (e.g. {@code 512} for {@code "1/512"}, {@code 42.67} for {@code "3/128"}),
	 * {@code -1} for guaranteed drops ({@code "Always"} / {@code "1/1"}), or {@code 0} for
	 * qualitative or unparseable rates.
	 */
	public static double parseDenominator(String rate)
	{
		if (rate == null)
		{
			return 0;
		}

		String trimmed = rate.trim();
		if (trimmed.isEmpty())
		{
			return 0;
		}

		if (trimmed.equalsIgnoreCase("Always") || trimmed.equals("1/1"))
		{
			return -1;
		}

		Matcher matcher = FRACTION.matcher(trimmed);
		if (matcher.find())
		{
			try
			{
				double numerator = Double.parseDouble(stripCommas(matcher.group(1)));
				double denominator = Double.parseDouble(stripCommas(matcher.group(2)));
				if (numerator > 0)
				{
					return denominator / numerator;
				}
			}
			catch (NumberFormatException e)
			{
				return 0;
			}
		}

		return 0;
	}

	public static boolean isAlways(String rate)
	{
		if (rate == null)
		{
			return false;
		}
		String trimmed = rate.trim();
		return trimmed.equalsIgnoreCase("Always") || trimmed.equals("1/1");
	}

	/** True if the rate is a qualitative label ("Common", "Uncommon", "Rare", "Very rare") rather than a number. */
	public static boolean isQualitative(String rate)
	{
		if (rate == null)
		{
			return false;
		}
		String trimmed = rate.trim();
		return trimmed.equalsIgnoreCase("Common")
			|| trimmed.equalsIgnoreCase("Uncommon")
			|| trimmed.equalsIgnoreCase("Rare")
			|| trimmed.equalsIgnoreCase("Very rare");
	}

	/**
	 * True if a numeric rate is at least as rare as the given threshold.
	 * {@code threshold <= 0} shows everything; {@code "Always"} and qualitative rates return false.
	 */
	public static boolean isRareEnough(String rate, int threshold)
	{
		if (threshold <= 0)
		{
			return true;
		}

		double denominator = parseDenominator(rate);
		if (denominator <= 0)
		{
			return false;
		}
		return denominator >= threshold;
	}

	/**
	 * The shared display-filter predicate: guaranteed drops only when {@code showGuaranteed}; numeric rates
	 * gated by {@code minimumRarity} ({@code <= 0} shows every numeric rate); qualitative labels only when
	 * {@code showQualitative}. Used by the ground, chat, inventory and reward-interface paths alike.
	 */
	public static boolean shouldDisplay(String rate, int minimumRarity, boolean showQualitative, boolean showGuaranteed)
	{
		if (rate == null || rate.trim().isEmpty())
		{
			return false;
		}
		if (isAlways(rate))
		{
			return showGuaranteed;
		}

		double denominator = parseDenominator(rate);
		if (denominator > 0)
		{
			return minimumRarity <= 0 || denominator >= minimumRarity;
		}

		return isQualitative(rate) && showQualitative;
	}

	/** Formats a rate for display in the user's chosen {@link RateFormat}. */
	public static String format(String rate, RateFormat format)
	{
		if (format == RateFormat.EXACT)
		{
			return formatRateFull(rate);
		}
		return oneInN(rate, format != RateFormat.ONE_IN_X);
	}

	/** Compact overlay format: rounded "1 in N" (so {@code 100/2,440} reads as {@code 1/24}). */
	public static String formatRate(String rate)
	{
		return oneInN(rate, true);
	}

	/**
	 * Normalises a rate to "1 in N": {@code rounded} gives a whole number ({@code 1/24}), otherwise one
	 * decimal place as the wiki renders it ({@code 1/24.4}). {@code Always} and qualitative labels pass
	 * through unchanged.
	 */
	private static String oneInN(String rate, boolean rounded)
	{
		if (rate == null)
		{
			return "";
		}

		String trimmed = rate.trim();
		if (isAlways(trimmed))
		{
			return "Always";
		}

		Matcher matcher = FRACTION.matcher(trimmed);
		if (!matcher.find())
		{
			return trimmed;
		}

		try
		{
			double numerator = Double.parseDouble(stripCommas(matcher.group(1)));
			double denominator = Double.parseDouble(stripCommas(matcher.group(2)));
			if (numerator > 0 && denominator > 0)
			{
				double n = denominator / numerator;
				if (rounded)
				{
					return "1/" + String.format(Locale.US, "%,d", Math.round(n));
				}
				double oneDecimal = Math.round(n * 10.0) / 10.0;
				return "1/" + (oneDecimal == Math.floor(oneDecimal)
					? String.format(Locale.US, "%,d", (long) oneDecimal)
					: String.format(Locale.US, "%.1f", oneDecimal));
			}
		}
		catch (NumberFormatException ignored)
		{
			// fall through to the raw fraction
		}

		return matcher.group(1) + "/" + matcher.group(2);
	}

	/**
	 * The rate exactly as the wiki records it — footnote stripped but NOT simplified. Used for chat,
	 * where there is room for the precise fraction (e.g. {@code 100/2,440}).
	 */
	public static String formatRateFull(String rate)
	{
		if (rate == null)
		{
			return "";
		}

		String trimmed = rate.trim();
		if (isAlways(trimmed))
		{
			return "Always";
		}

		Matcher matcher = FRACTION.matcher(trimmed);
		if (matcher.find())
		{
			return matcher.group(1) + "/" + matcher.group(2);
		}
		return trimmed;
	}

	private static String stripCommas(String number)
	{
		return number.replace(",", "");
	}
}

package com.dropratedisplay;

import java.util.List;
import lombok.Data;

/**
 * A single drop-table entry as loaded from {@code drop_rates.json}.
 *
 * <p>Entries are stored keyed by item <b>name</b> (the OSRS Wiki does not expose numeric item ids in
 * its drop data), so {@link #itemName} is populated from the map key at load time and is not present
 * in the JSON itself.
 *
 * <p>A handful of items are dropped at several different quantities, each with its own rate (e.g. an
 * Ammonite Crab drops Numulite &times;4 at 29/128 but &times;2 at 8/128). The primary {@link #rate}/
 * {@link #quantity} hold the first such row; the rest live in {@link #variants}. Use
 * {@link #selectForQuantity(int)} to pick the row matching the stack the player actually received.
 */
@Data
public class DropRateEntry
{
	private static final int MATCH_NONE = 0;
	private static final int MATCH_RANGE = 1;
	private static final int MATCH_EXACT = 2;

	/** Drop rate string exactly as the wiki displays it, e.g. {@code "1/512"}, {@code "Always"}, {@code "Uncommon"}. */
	private String rate;

	/** Quantity string, e.g. {@code "1"}, {@code "1-3"}, or the non-numeric {@code "Unknown"}/{@code "Varies"}. */
	private String quantity;

	/**
	 * Other rows for the same item at different quantities (each with its own rate + quantity). Null for
	 * the overwhelming majority of items, which drop at a single quantity. A variant's own {@code variants}
	 * list is always null -- the nesting is only one level deep.
	 */
	private List<DropRateEntry> variants;

	/** The item name (the JSON map key). Populated at load time; not serialised. */
	private transient String itemName;

	/**
	 * Chooses the row whose quantity best matches {@code received}: an exact single-quantity row wins,
	 * else a row whose range contains it, else this entry itself (the fallback for quantities the wiki
	 * does not list). Returns {@code this} immediately when there are no variants, the case for almost
	 * every item.
	 */
	DropRateEntry selectForQuantity(int received)
	{
		if (variants == null || variants.isEmpty())
		{
			return this;
		}

		DropRateEntry rangeMatch = null;
		int selfKind = quantityMatch(received);
		if (selfKind == MATCH_EXACT)
		{
			return this;
		}
		if (selfKind == MATCH_RANGE)
		{
			rangeMatch = this;
		}

		for (DropRateEntry variant : variants)
		{
			int kind = variant.quantityMatch(received);
			if (kind == MATCH_EXACT)
			{
				return variant;
			}
			if (kind == MATCH_RANGE && rangeMatch == null)
			{
				rangeMatch = variant;
			}
		}
		return rangeMatch != null ? rangeMatch : this;
	}

	/** Classifies how this row's quantity spec matches a received count: exact single, in-range, or none. */
	private int quantityMatch(int received)
	{
		if (quantity == null)
		{
			return MATCH_NONE;
		}

		String q = quantity.trim();
		int dash = q.indexOf('-');
		try
		{
			if (dash > 0)
			{
				int low = Integer.parseInt(q.substring(0, dash).trim());
				int high = Integer.parseInt(q.substring(dash + 1).trim());
				return (received >= low && received <= high) ? MATCH_RANGE : MATCH_NONE;
			}
			return Integer.parseInt(q) == received ? MATCH_EXACT : MATCH_NONE;
		}
		catch (NumberFormatException e)
		{
			return MATCH_NONE; // non-numeric quantities ("Unknown", "Varies") never match a specific count
		}
	}
}

package com.dropratedisplay;

import java.awt.Color;
import java.util.Locale;

/**
 * Buckets a drop rate into a rarity tier and resolves the tier's configured colour, so a glance at the
 * colour tells you roughly how rare a drop is. Thresholds climb {@code 1/50 -> 1/500 -> 1/5,000 -> rarer};
 * guaranteed drops sit at the common end and qualitative labels map to the obvious tier.
 */
final class RarityColor
{
	enum Tier
	{
		COMMON, UNCOMMON, RARE, ULTRA_RARE
	}

	private RarityColor()
	{
	}

	/** The rarity tier for a rate by its effective "1 in N" denominator (or by its qualitative label). */
	static Tier tierFor(String rate)
	{
		double denominator = RateParser.parseDenominator(rate);
		if (denominator < 0)
		{
			// "Always" — guaranteed, i.e. the least rare thing there is.
			return Tier.COMMON;
		}
		if (denominator == 0)
		{
			// Qualitative label (or unparseable): map the label to the obvious tier.
			String label = rate == null ? "" : rate.trim().toLowerCase(Locale.ROOT);
			switch (label)
			{
				case "very rare":
					return Tier.ULTRA_RARE;
				case "rare":
					return Tier.RARE;
				case "uncommon":
					return Tier.UNCOMMON;
				default:
					return Tier.COMMON;
			}
		}
		if (denominator <= 50)
		{
			return Tier.COMMON;
		}
		if (denominator <= 500)
		{
			return Tier.UNCOMMON;
		}
		if (denominator <= 5000)
		{
			return Tier.RARE;
		}
		return Tier.ULTRA_RARE;
	}

	/** The configured colour for a rate's rarity tier. */
	static Color colour(String rate, DropRateDisplayConfig config)
	{
		switch (tierFor(rate))
		{
			case UNCOMMON:
				return config.uncommonColour();
			case RARE:
				return config.rareColour();
			case ULTRA_RARE:
				return config.ultraRareColour();
			case COMMON:
			default:
				return config.commonColour();
		}
	}
}

package com.dropratedisplay;

import com.google.common.collect.HashBasedTable;
import com.google.common.collect.Table;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Mirrors the core Ground Items plugin's per-tile item table so our merged rates land on the exact rows it
 * draws — without reflection.
 *
 * <p>Ground Items rows its items in the iteration order of a Guava {@link HashBasedTable} keyed by tile and
 * item id. That order is <b>not</b> any simple function of the id (neither {@code id & 15} ascending nor
 * descending matches — it depends on the table's internal bucket layout and insert history), so it can't be
 * reproduced by sorting. Instead we keep an <i>identical</i> {@code HashBasedTable}, fed the same
 * {@code ItemSpawned}/{@code ItemDespawned} operations (insert on spawn, subtract/remove on despawn) from
 * the same events. The same class plus the same operations yields the same per-tile key iteration order by
 * construction — {@code row(tile).keySet()} equals Ground Items' row order.
 */
@Singleton
class GroundItemTracker
{
	// HashBasedTable is not thread-safe; all access is guarded on this monitor.
	private final Table<WorldPoint, Integer, Integer> table = HashBasedTable.create();

	/** Insert on spawn (same as Ground Items: new id added; repeat id just sums, leaving the key in place). */
	synchronized void add(WorldPoint tile, int itemId, int quantity)
	{
		if (tile == null)
		{
			return;
		}
		final Integer existing = table.get(tile, itemId);
		table.put(tile, itemId, existing == null ? quantity : existing + quantity);
	}

	/** On despawn, subtract; remove the id when it is depleted (Ground Items drops the cell too). */
	synchronized void remove(WorldPoint tile, int itemId, int quantity)
	{
		if (tile == null)
		{
			return;
		}
		final Integer existing = table.get(tile, itemId);
		if (existing == null)
		{
			return;
		}
		if (existing <= quantity)
		{
			table.remove(tile, itemId);
		}
		else
		{
			table.put(tile, itemId, existing - quantity);
		}
	}

	synchronized void clear()
	{
		table.clear();
	}

	/** Item ids on the tile in Ground Items' row order; empty if none are tracked. */
	synchronized List<Integer> orderedIds(WorldPoint tile)
	{
		if (!table.containsRow(tile))
		{
			return Collections.emptyList();
		}
		return new ArrayList<>(table.row(tile).keySet());
	}

	/** True while the tile still holds this id (i.e. it has not been fully picked up / despawned). */
	synchronized boolean contains(WorldPoint tile, int itemId)
	{
		return table.contains(tile, itemId);
	}
}

package com.dropratedisplay;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemLayer;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.WildcardMatcher;

/**
 * Draws drop rates for monster floor loot.
 *
 * <p>In <b>merge</b> mode the rate is placed flush after each item's line, on the correct row, so it
 * reads as one line with the core Ground Items plugin ({@code Abyssal whip (1/512)}) even for a pile of
 * 2+ drops. Rather than read Ground Items' internal state, we <i>reproduce</i> its layout entirely from
 * public data: the tile's items and quantities come from the live scene ({@link Tile#getGroundItems()}),
 * the per-row order comes from {@link GroundItemTracker} (which mirrors Ground Items' own table so the
 * order is identical, rather than guessing its HashMap bucket order), and each line is rebuilt as
 * {@code name (qty) (GE: x gp) (HA: y gp)} honouring the Ground Items {@code priceDisplayMode} config —
 * matching the exact string width it draws.
 *
 * <p>Ground Items also skips items it hides (its hidden list, "hide under value", "show highlighted only")
 * from <i>both</i> drawing and its row count. When {@link DropRateDisplayConfig#hideHiddenByGroundItems()}
 * is on we reproduce that from its config, so hidden items neither get a floating rate nor shift the rows
 * of the items that are drawn.
 *
 * <p>In <b>standalone</b> mode (for players without Ground Items) it draws a self-labelled
 * {@code "Item (rate)"} line instead. Either way, presence is taken from the live scene, so a rate
 * vanishes the instant its item is picked up, and format/colour/filter are applied every frame so config
 * changes update what is already on screen. Styling is always ours — Ground Items' colours are never read.
 */
@Singleton
public class DropRateDisplayOverlay extends Overlay
{
	private static final int MAX_ENTRIES = 256;
	private static final int STRING_GAP = 15;   // Ground Items' per-row vertical gap
	private static final int OFFSET_Z = 20;     // Ground Items' text height offset
	private static final int GAP_PX = 4;        // gap between the item's line and our appended rate
	private static final int COINS = 995;       // Ground Items shows no price for coins

	// Ground Items' isHiddenOrHighlighted() states.
	private static final int ST_NONE = 0;
	private static final int ST_HIGHLIGHT = 1;
	private static final int ST_HIDDEN = 2;
	// Ground Items' default hidden list, used when the user has never changed it.
	private static final String DEFAULT_HIDDEN = "Vial, Ashes, Coins, Bones, Bucket, Jug, Seaweed";

	private final Client client;
	private final DropRateDisplayConfig config;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final GroundItemTracker groundItems;

	/** Guarded by its own monitor; mutated from loot events and read from the render thread. */
	private final List<GroundRate> rates = new ArrayList<>();

	@Inject
	DropRateDisplayOverlay(Client client, DropRateDisplayConfig config, ItemManager itemManager,
		ConfigManager configManager, GroundItemTracker groundItems)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.groundItems = groundItems;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void addGroundRate(WorldPoint point, int itemId, String itemName, String rate)
	{
		if (point == null || itemName == null || rate == null)
		{
			return;
		}

		synchronized (rates)
		{
			// One entry per (tile, item); a fresh drop replaces the old rate. No timer — the entry lives
			// until its item leaves the floor (pruned on despawn), so the rate stays exactly as long as the
			// ground item does.
			rates.removeIf(r -> r.itemId == itemId && r.point.equals(point));
			rates.add(new GroundRate(point, itemId, itemName, rate));
			while (rates.size() > MAX_ENTRIES)
			{
				rates.remove(0);
			}
		}
	}

	/** Drop the rate when its item is fully gone from the tile (picked up / despawned). */
	void removeGroundRate(WorldPoint point, int itemId)
	{
		synchronized (rates)
		{
			rates.removeIf(r -> r.itemId == itemId && r.point.equals(point));
		}
	}

	void clear()
	{
		synchronized (rates)
		{
			rates.clear();
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGroundItemRates())
		{
			return null;
		}

		final List<GroundRate> snapshot;
		synchronized (rates)
		{
			if (rates.isEmpty())
			{
				return null;
			}
			snapshot = new ArrayList<>(rates);
		}

		// Group the visible rated drops by tile. Filter here (not at capture) so config changes apply live.
		final Map<WorldPoint, List<GroundRate>> byTile = new LinkedHashMap<>();
		for (GroundRate r : snapshot)
		{
			if (!RateParser.shouldDisplay(r.rate, config.minimumRarity(), config.showQualitativeRates(),
				config.showGuaranteedDrops()))
			{
				continue;
			}
			byTile.computeIfAbsent(r.point, k -> new ArrayList<>()).add(r);
		}
		if (byTile.isEmpty())
		{
			return null;
		}

		final boolean merge = config.mergeWithGroundItems();
		final PriceMode priceMode = merge ? readGroundItemsPriceMode() : PriceMode.OFF;
		final GiHide giHide = merge && config.hideHiddenByGroundItems() ? readGiHide() : null;
		final FontMetrics fm = graphics.getFontMetrics();

		for (Map.Entry<WorldPoint, List<GroundRate>> e : byTile.entrySet())
		{
			final LocalPoint localPoint = LocalPoint.fromWorld(client, e.getKey());
			if (localPoint == null)
			{
				continue;
			}

			final Tile tile = tileAt(e.getKey(), localPoint);
			if (tile == null)
			{
				continue;
			}

			final List<TileEntry> pile = orderedPile(tile, e.getKey());
			if (pile.isEmpty())
			{
				continue; // everything on this tile has been picked up
			}

			final int height = itemLayerHeight(tile);
			if (merge)
			{
				renderMerged(graphics, localPoint, height, pile, e.getValue(), priceMode, giHide, fm);
			}
			else
			{
				renderStandalone(graphics, localPoint, height, pile, e.getValue());
			}
		}

		return null;
	}

	/**
	 * Appends each rated item's rate flush after its reconstructed Ground Items line, on its own row.
	 * Items Ground Items hides are skipped exactly as it skips them (before the row is counted), so the
	 * remaining rows line up with what Ground Items actually draws.
	 */
	private void renderMerged(Graphics2D graphics, LocalPoint localPoint, int height, List<TileEntry> pile,
		List<GroundRate> rated, PriceMode priceMode, GiHide giHide, FontMetrics fm)
	{
		final Map<Integer, GroundRate> rateById = byId(rated);

		int offset = 0;
		for (TileEntry entry : pile)
		{
			final GroundRate r = rateById.get(entry.id);
			final ItemInfo info = (giHide != null || r != null) ? itemInfo(entry.id, entry.quantity) : null;

			if (giHide != null && giHide.hides(info))
			{
				continue; // Ground Items doesn't draw this row, so it takes no offset here either
			}

			if (r != null)
			{
				final String line = buildGroundItemsLine(info, entry.quantity, priceMode);
				final Point textPoint = Perspective.getCanvasTextLocation(client, graphics, localPoint, line, height + OFFSET_Z);
				if (textPoint != null)
				{
					final int x = textPoint.getX() + fm.stringWidth(line) + GAP_PX;
					final int y = textPoint.getY() - STRING_GAP * offset;
					drawRate(graphics, x, y, RateParser.format(r.rate, config.groundRateFormat()), r.rate);
				}
			}
			offset++;
		}
	}

	/** Self-labelled {@code "Item (rate)"} rows, for players not running Ground Items. */
	private void renderStandalone(Graphics2D graphics, LocalPoint localPoint, int height, List<TileEntry> pile,
		List<GroundRate> rated)
	{
		final Map<Integer, GroundRate> rateById = byId(rated);
		int offset = 0;
		for (TileEntry entry : pile)
		{
			final GroundRate r = rateById.get(entry.id);
			if (r == null)
			{
				continue;
			}

			final String rateText = RateParser.format(r.rate, config.groundRateFormat());
			final String text = r.itemName + " (" + rateText + ")";
			final Point textPoint = Perspective.getCanvasTextLocation(client, graphics, localPoint, text, height + OFFSET_Z);
			if (textPoint != null)
			{
				drawRate(graphics, textPoint.getX(), textPoint.getY() - STRING_GAP * offset, text, r.rate);
				offset++;
			}
		}
	}

	/**
	 * The tile's items in Ground Items' exact row order. Presence and quantities come from the live scene
	 * (authoritative for what is still on the ground and how many); the order comes from
	 * {@link GroundItemTracker}, which mirrors Ground Items' own {@code HashBasedTable}. Anything the tracker
	 * missed (e.g. it spawned before this plugin started) falls back to the end, in scene order.
	 */
	private List<TileEntry> orderedPile(Tile sceneTile, WorldPoint tilePoint)
	{
		final List<TileItem> items = sceneTile.getGroundItems();
		if (items == null || items.isEmpty())
		{
			return Collections.emptyList();
		}

		final Map<Integer, Integer> qtyById = new LinkedHashMap<>();
		for (TileItem it : items)
		{
			qtyById.merge(it.getId(), it.getQuantity(), Integer::sum);
		}

		final List<TileEntry> pile = new ArrayList<>(qtyById.size());
		for (int id : groundItems.orderedIds(tilePoint))
		{
			final Integer qty = qtyById.remove(id);
			if (qty != null)
			{
				pile.add(new TileEntry(id, qty));
			}
		}
		for (Map.Entry<Integer, Integer> en : qtyById.entrySet())
		{
			pile.add(new TileEntry(en.getKey(), en.getValue()));
		}
		return pile;
	}

	/** Rebuilds the exact text Ground Items draws for an item, so we know where its line ends. */
	private String buildGroundItemsLine(ItemInfo info, int quantity, PriceMode priceMode)
	{
		final StringBuilder sb = new StringBuilder(info.name);
		if (quantity > 1)
		{
			sb.append(" (").append(QuantityFormatter.quantityToStackSize(quantity)).append(')');
		}

		if (info.id != COINS && priceMode != PriceMode.OFF)
		{
			if (priceMode == PriceMode.BOTH)
			{
				if (info.gePrice > 0)
				{
					sb.append(" (GE: ").append(QuantityFormatter.quantityToStackSize(info.gePrice)).append(" gp)");
				}
				if (info.haPrice > 0)
				{
					sb.append(" (HA: ").append(QuantityFormatter.quantityToStackSize(info.haPrice)).append(" gp)");
				}
			}
			else
			{
				final int price = priceMode == PriceMode.GE ? info.gePrice : info.haPrice;
				if (price > 0)
				{
					sb.append(" (").append(QuantityFormatter.quantityToStackSize(price)).append(" gp)");
				}
			}
		}

		return sb.toString();
	}

	/** Per-item data Ground Items derives the same way (total GE/HA value, tradeable flag). */
	private ItemInfo itemInfo(int id, int quantity)
	{
		final ItemComposition comp = itemManager.getItemComposition(id);
		final int realId = comp.getNote() != -1 ? comp.getLinkedNoteId() : id;
		final int unitGe;
		final int unitHa;
		if (realId == COINS)
		{
			unitGe = 1;
			unitHa = 1;
		}
		else
		{
			unitGe = itemManager.getItemPrice(realId);
			unitHa = comp.getHaPrice();
		}
		return new ItemInfo(id, comp.getName(), unitGe * quantity, unitHa * quantity, comp.isGeTradeable());
	}

	private PriceMode readGroundItemsPriceMode()
	{
		switch (giConfig("priceDisplayMode", "BOTH"))
		{
			case "OFF":
				return PriceMode.OFF;
			case "GE":
				return PriceMode.GE;
			case "HA":
				return PriceMode.HA;
			default:
				return PriceMode.BOTH;
		}
	}

	private GiHide readGiHide()
	{
		final List<String> hidden = splitCsv(giConfig("hiddenItems", DEFAULT_HIDDEN));
		final List<String> highlight = splitCsv(giConfig("highlightedItems", ""));
		final int hideUnderValue = parseIntOr(configManager.getConfiguration("grounditems", "hideUnderValue"), 0);
		final boolean showHighlightedOnly = "true".equals(configManager.getConfiguration("grounditems", "showHighlightedOnly"));
		final boolean dontHideUntradeables = !"false".equals(configManager.getConfiguration("grounditems", "dontHideUntradeables"));
		return new GiHide(hidden, highlight, hideUnderValue, showHighlightedOnly, dontHideUntradeables);
	}

	private String giConfig(String key, String def)
	{
		final String v = configManager.getConfiguration("grounditems", key);
		return v != null ? v : def;
	}

	private Tile tileAt(WorldPoint worldPoint, LocalPoint localPoint)
	{
		final Tile[][][] tiles = client.getScene().getTiles();
		final int plane = worldPoint.getPlane();
		if (plane < 0 || plane >= tiles.length)
		{
			return null;
		}
		final int x = localPoint.getSceneX();
		final int y = localPoint.getSceneY();
		if (x < 0 || y < 0 || x >= tiles[plane].length || y >= tiles[plane][x].length)
		{
			return null;
		}
		return tiles[plane][x][y];
	}

	private static int itemLayerHeight(Tile tile)
	{
		final ItemLayer layer = tile.getItemLayer();
		return layer != null ? layer.getHeight() : 0;
	}

	private static Map<Integer, GroundRate> byId(List<GroundRate> rated)
	{
		final Map<Integer, GroundRate> map = new HashMap<>();
		for (GroundRate r : rated)
		{
			map.putIfAbsent(r.itemId, r);
		}
		return map;
	}

	private static List<String> splitCsv(String csv)
	{
		final List<String> out = new ArrayList<>();
		for (String s : csv.split(","))
		{
			final String t = s.trim();
			if (!t.isEmpty())
			{
				out.add(t);
			}
		}
		return out;
	}

	private static int parseIntOr(String v, int def)
	{
		if (v == null)
		{
			return def;
		}
		try
		{
			return Integer.parseInt(v.trim());
		}
		catch (NumberFormatException e)
		{
			return def;
		}
	}

	private void drawRate(Graphics2D graphics, int x, int y, String text, String rateForColour)
	{
		final TextComponent component = new TextComponent();
		component.setText(text);
		component.setColor(RarityColor.colour(rateForColour, config));
		component.setOutline(true);
		component.setPosition(x, y);
		component.render(graphics);
	}

	private enum PriceMode
	{
		OFF, GE, HA, BOTH
	}

	/** Reproduces Ground Items' hide decision purely from its public config. */
	private static final class GiHide
	{
		private final List<String> hidden;
		private final List<String> highlight;
		private final int hideUnderValue;
		private final boolean showHighlightedOnly;
		private final boolean dontHideUntradeables;

		private GiHide(List<String> hidden, List<String> highlight, int hideUnderValue,
			boolean showHighlightedOnly, boolean dontHideUntradeables)
		{
			this.hidden = hidden;
			this.highlight = highlight;
			this.hideUnderValue = hideUnderValue;
			this.showHighlightedOnly = showHighlightedOnly;
			this.dontHideUntradeables = dontHideUntradeables;
		}

		/** True when Ground Items would not draw this item (so we skip it, matching its row count). */
		private boolean hides(ItemInfo info)
		{
			final int state = state(info.name);
			if (state == ST_HIGHLIGHT)
			{
				return false; // highlight always draws, and takes priority over hide
			}
			final boolean canBeHidden = info.gePrice > 0 || info.tradeable || !dontHideUntradeables;
			final boolean underValue = info.gePrice < hideUnderValue && info.haPrice < hideUnderValue;
			final boolean hidden = state == ST_HIDDEN || (canBeHidden && underValue);
			return hidden || showHighlightedOnly;
		}

		/** Ground Items' isHiddenOrHighlighted(): exact match wins over wildcard, highlight over hide. */
		private int state(String name)
		{
			if (matchesExact(highlight, name))
			{
				return ST_HIGHLIGHT;
			}
			if (matchesExact(hidden, name))
			{
				return ST_HIDDEN;
			}
			if (matchesWildcard(highlight, name))
			{
				return ST_HIGHLIGHT;
			}
			if (matchesWildcard(hidden, name))
			{
				return ST_HIDDEN;
			}
			return ST_NONE;
		}

		private static boolean matchesExact(List<String> list, String name)
		{
			for (String entry : list)
			{
				if (!entry.contains("*") && entry.equalsIgnoreCase(name))
				{
					return true;
				}
			}
			return false;
		}

		private static boolean matchesWildcard(List<String> list, String name)
		{
			for (String entry : list)
			{
				if (entry.contains("*") && WildcardMatcher.matches(entry, name))
				{
					return true;
				}
			}
			return false;
		}
	}

	private static final class ItemInfo
	{
		private final int id;
		private final String name;
		private final int gePrice;
		private final int haPrice;
		private final boolean tradeable;

		private ItemInfo(int id, String name, int gePrice, int haPrice, boolean tradeable)
		{
			this.id = id;
			this.name = name;
			this.gePrice = gePrice;
			this.haPrice = haPrice;
			this.tradeable = tradeable;
		}
	}

	private static final class TileEntry
	{
		private final int id;
		private final int quantity;

		private TileEntry(int id, int quantity)
		{
			this.id = id;
			this.quantity = quantity;
		}
	}

	private static final class GroundRate
	{
		private final WorldPoint point;
		private final int itemId;
		private final String itemName;
		private final String rate;

		private GroundRate(WorldPoint point, int itemId, String itemName, String rate)
		{
			this.point = point;
			this.itemId = itemId;
			this.itemName = itemName;
			this.rate = rate;
		}
	}
}

package com.dropratedisplay;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Getter;

/**
 * The drop table for a single loot source (a monster, a salvage tier, a reward casket, etc.), as
 * loaded from {@code drop_rates.json}.
 *
 * <p>Drops are keyed by item name. A case-insensitive index is built at load time so lookups still
 * succeed when the in-game item name differs from the wiki spelling only by case.
 */
public class SourceDropTable
{
	/** OSRS Wiki monster ids for this source (used to disambiguate same-named NPC variants). May be null. */
	@Getter
	private List<Integer> npcIds;

	/** The wiki source name (the JSON map key). Populated at load time; not serialised. */
	@Getter
	private transient String sourceName;

	/** Drops keyed by item name. */
	private Map<String, DropRateEntry> drops;

	private transient Map<String, DropRateEntry> lowerCaseIndex;

	void setSourceName(String sourceName)
	{
		this.sourceName = sourceName;
	}

	/**
	 * Builds the case-insensitive lookup index and back-fills each entry's item name from its key.
	 * Called once after Gson deserialisation.
	 */
	void index()
	{
		lowerCaseIndex = new HashMap<>();
		if (drops == null)
		{
			return;
		}

		for (Map.Entry<String, DropRateEntry> e : drops.entrySet())
		{
			DropRateEntry entry = e.getValue();
			if (entry != null)
			{
				entry.setItemName(e.getKey());
				if (entry.getVariants() != null)
				{
					for (DropRateEntry variant : entry.getVariants())
					{
						if (variant != null)
						{
							variant.setItemName(e.getKey());
						}
					}
				}
				lowerCaseIndex.put(e.getKey().toLowerCase(Locale.ROOT), entry);
			}
		}
	}

	/**
	 * Looks up a drop by item name (exact match first, then case-insensitive).
	 *
	 * @return the matching entry, or null if this source does not drop the item (or has no known rate).
	 */
	public DropRateEntry getDrop(String itemName)
	{
		if (itemName == null || drops == null)
		{
			return null;
		}

		DropRateEntry entry = drops.get(itemName);
		if (entry == null && lowerCaseIndex != null)
		{
			entry = lowerCaseIndex.get(itemName.toLowerCase(Locale.ROOT));
		}
		return entry;
	}

	/**
	 * Looks up a drop by item name, then narrows to the row matching {@code quantity} -- so an item the
	 * wiki lists at several quantities (e.g. Numulite &times;2 vs &times;4, each with its own rate)
	 * resolves to the rate for the stack actually received. Falls back to the primary row when no
	 * quantity row matches.
	 *
	 * @return the matching entry, or null if this source does not drop the item (or has no known rate).
	 */
	public DropRateEntry getDrop(String itemName, int quantity)
	{
		DropRateEntry entry = getDrop(itemName);
		return entry == null ? null : entry.selectForQuantity(quantity);
	}

	public boolean matchesNpcId(int npcId)
	{
		return npcIds != null && npcIds.contains(npcId);
	}
}

package com.dropratedisplay;

/**
 * How a drop rate is written for display.
 *
 * <ul>
 *   <li>{@link #EXACT} — the wiki's own fraction, e.g. {@code 100/2,440}, {@code 3/128}, {@code 1/512}.</li>
 *   <li>{@link #ONE_IN_X} — normalised to "1 in N" with a decimal, e.g. {@code 1/24.4} (as the wiki renders it).</li>
 *   <li>{@link #ONE_IN_X_ROUNDED} — "1 in N" rounded to a whole number, e.g. {@code 1/24}.</li>
 * </ul>
 */
public enum RateFormat
{
	EXACT("Exact"),
	ONE_IN_X("1 in X"),
	ONE_IN_X_ROUNDED("1 in X (rounded)");

	private final String label;

	RateFormat(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.dropratedisplay;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Briefly draws the drop rate on inventory items that were just received from a non-floor source
 * (pickpocket, salvage, chest reward). Entries expire after {@link #EXPIRY_MS}. Useful for salvage,
 * where the loot never touches the ground so the ground overlay can't show it.
 */
@Singleton
public class DropRateInventoryOverlay extends WidgetItemOverlay
{
	private static final long EXPIRY_MS = 30_000L;

	private final DropRateDisplayConfig config;

	/** itemId -&gt; (rate text, expiry). Written from loot events, read from the render thread. */
	private final Map<Integer, TimedRate> rates = new ConcurrentHashMap<>();

	@Inject
	DropRateInventoryOverlay(DropRateDisplayConfig config)
	{
		this.config = config;
		// Inventory only: reward-interface pop-ups are handled by RewardInterfaceOverlay (drawn directly
		// from the source table), so we do not also register the interfaces here and double-draw.
		showOnInventory();
	}

	void addRate(int itemId, String rate)
	{
		rates.put(itemId, new TimedRate(rate, System.currentTimeMillis() + EXPIRY_MS));
	}

	void clear()
	{
		rates.clear();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showInventoryRates())
		{
			return;
		}

		TimedRate rate = rates.get(itemId);
		if (rate == null)
		{
			return;
		}
		if (rate.expiresAt <= System.currentTimeMillis())
		{
			rates.remove(itemId);
			return;
		}

		// Filter/format/colour are all applied here from the raw rate, so config changes update live.
		if (!RateParser.shouldDisplay(rate.rate, config.minimumRarity(),
			config.showQualitativeRates(), config.showGuaranteedDrops()))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		TextComponent text = new TextComponent();
		text.setText(RateParser.format(rate.rate, config.inventoryRateFormat()));
		text.setColor(RarityColor.colour(rate.rate, config));
		text.setOutline(true);
		// Bottom-left of the slot, clear of the top-left quantity numbers.
		text.setPosition(bounds.x - 1, bounds.y + bounds.height - 1);
		text.render(graphics);
	}

	private static final class TimedRate
	{
		private final String rate;
		private final long expiresAt;

		private TimedRate(String rate, long expiresAt)
		{
			this.rate = rate;
			this.expiresAt = expiresAt;
		}
	}
}

package com.dropratedisplay;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(DropRateDisplayConfig.GROUP)
public interface DropRateDisplayConfig extends Config
{
	String GROUP = "dropratedisplay";

	@ConfigSection(
		name = "Displays",
		description = "Where drop rates are shown",
		position = 1
	)
	String DISPLAYS_SECTION = "displays";

	@ConfigSection(
		name = "Filters",
		description = "Which rates are shown",
		position = 2
	)
	String FILTERS_SECTION = "filters";

	@ConfigSection(
		name = "Rate format",
		description = "How the rate reads on each surface. Exact: 100/2,440. 1 in X: 1/24.4. Rounded: 1/24.",
		position = 3
	)
	String FORMAT_SECTION = "format";

	@ConfigSection(
		name = "Rarity colours",
		description = "The rate is coloured by how rare the drop is; set each tier's colour here",
		position = 4
	)
	String COLOUR_SECTION = "colours";

	// --- Displays ---------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "showGroundItemRates",
		name = "Ground items",
		description = "Display drop rates where a monster died (appended to the Ground Items line when that plugin is on)",
		section = DISPLAYS_SECTION,
		position = 1
	)
	default boolean showGroundItemRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showChatRates",
		name = "Chat",
		description = "Print drop rates in the chatbox for pickpocket, salvage and chest loot",
		section = DISPLAYS_SECTION,
		position = 2
	)
	default boolean showChatRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInventoryRates",
		name = "Inventory items",
		description = "Briefly show the drop rate on items received from pickpockets, salvage and chests (about 30 seconds)",
		section = DISPLAYS_SECTION,
		position = 3
	)
	default boolean showInventoryRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRewardInterfaceRates",
		name = "Reward screens",
		description = "Draw drop rates over the items shown on reward screens (Barrows, raids, Moons, caskets, etc.)",
		section = DISPLAYS_SECTION,
		position = 4
	)
	default boolean showRewardInterfaceRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "mergeWithGroundItems",
		name = "Merge with Ground Items",
		description = "Place the rate flush after each item's Ground Items line (e.g. \"Abyssal whip (1/512)\"), "
			+ "aligned per item for 2+ drops. Turn off if you don't run the Ground Items plugin to get a "
			+ "self-labelled \"Item (rate)\" line instead.",
		section = DISPLAYS_SECTION,
		position = 5
	)
	default boolean mergeWithGroundItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideHiddenByGroundItems",
		name = "Hide rates for items hidden by Ground Items",
		description = "In merge mode, don't draw a rate for items the Ground Items plugin itself hides (its "
			+ "hidden list, \"hide under value\", or \"show highlighted only\"). Stops rates floating with no "
			+ "item text and keeps the rows aligned. Reads Ground Items' own config; no effect with merge off.",
		section = DISPLAYS_SECTION,
		position = 6
	)
	default boolean hideHiddenByGroundItems()
	{
		return true;
	}

	// --- Filters ----------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "minimumRarity",
		name = "Minimum rarity",
		description = "Only show rates for items rarer than this (e.g. 25 means 1/25 or rarer). Set to 0 to show all.",
		section = FILTERS_SECTION,
		position = 1
	)
	default int minimumRarity()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "showQualitativeRates",
		name = "Show qualitative rates",
		description = "Display 'Uncommon', 'Rare' etc. when the exact rate is unknown",
		section = FILTERS_SECTION,
		position = 2
	)
	default boolean showQualitativeRates()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showGuaranteedDrops",
		name = "Show guaranteed drops",
		description = "Also show 'Always' for 100% drops such as bones and ashes",
		section = FILTERS_SECTION,
		position = 3
	)
	default boolean showGuaranteedDrops()
	{
		return false;
	}

	// --- Rate format (roomy surfaces default exact, tiny icons rounded) ---------------------------

	@ConfigItem(
		keyName = "groundRateFormat",
		name = "Floor drops",
		description = "How the rate reads on ground items",
		section = FORMAT_SECTION,
		position = 1
	)
	default RateFormat groundRateFormat()
	{
		return RateFormat.EXACT;
	}

	@ConfigItem(
		keyName = "chatRateFormat",
		name = "Chat",
		description = "How the rate reads in chat",
		section = FORMAT_SECTION,
		position = 2
	)
	default RateFormat chatRateFormat()
	{
		return RateFormat.EXACT;
	}

	@ConfigItem(
		keyName = "rewardRateFormat",
		name = "Reward screens",
		description = "How the rate reads on reward-screen items",
		section = FORMAT_SECTION,
		position = 3
	)
	default RateFormat rewardRateFormat()
	{
		return RateFormat.ONE_IN_X_ROUNDED;
	}

	@ConfigItem(
		keyName = "inventoryRateFormat",
		name = "Inventory items",
		description = "How the rate reads on inventory item icons",
		section = FORMAT_SECTION,
		position = 4
	)
	default RateFormat inventoryRateFormat()
	{
		return RateFormat.ONE_IN_X_ROUNDED;
	}

	// --- Rarity colours (thresholds: <=1/50, <=1/500, <=1/5,000, then rarer) ----------------------

	@ConfigItem(
		keyName = "commonColour",
		name = "Common",
		description = "Colour for common drops (1/50 or more common)",
		section = COLOUR_SECTION,
		position = 1
	)
	default Color commonColour()
	{
		return new Color(255, 224, 66); // yellow
	}

	@ConfigItem(
		keyName = "uncommonColour",
		name = "Uncommon",
		description = "Colour for uncommon drops (rarer than 1/50, up to 1/500)",
		section = COLOUR_SECTION,
		position = 2
	)
	default Color uncommonColour()
	{
		return new Color(86, 214, 86); // green
	}

	@ConfigItem(
		keyName = "rareColour",
		name = "Rare",
		description = "Colour for rare drops (rarer than 1/500, up to 1/5,000)",
		section = COLOUR_SECTION,
		position = 3
	)
	default Color rareColour()
	{
		return new Color(190, 120, 255); // purple
	}

	@ConfigItem(
		keyName = "ultraRareColour",
		name = "Ultra-rare",
		description = "Colour for ultra-rare drops (rarer than 1/5,000)",
		section = COLOUR_SECTION,
		position = 4
	)
	default Color ultraRareColour()
	{
		return new Color(255, 74, 74); // red
	}
}

package com.dropratedisplay;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Draws drop-rate text directly over the items shown on a reward interface, rather than in chat.
 *
 * <p>A reward screen (unlike a monster kill) renders every possible reward as an item widget, so the
 * rate can be looked up straight from that interface's drop-table source and painted on the item — no
 * loot detection needed. {@link WidgetItemOverlay} invokes {@link #renderItemOverlay} once per item
 * widget on the registered interfaces; the item's widget id tells us which interface, hence which source.
 *
 * <p>Clue caskets reuse one interface across all tiers, so their source is set dynamically by the plugin.
 */
@Singleton
public class RewardInterfaceOverlay extends WidgetItemOverlay
{
	/**
	 * Reward interface group id &rarr; the drop-table source it represents. Activity names here are mapped
	 * to the real wiki page by {@link DropRateDataStore}'s overrides (e.g. Chambers of Xeric &rarr; Ancient
	 * chest). Clue caskets are handled separately because their source depends on the completed tier.
	 */
	private static final Map<Integer, String> INTERFACE_SOURCES = new HashMap<>();

	static
	{
		INTERFACE_SOURCES.put(InterfaceID.BARROWS_REWARD, "Barrows");
		INTERFACE_SOURCES.put(InterfaceID.RAIDS_REWARDS, "Chambers of Xeric");
		INTERFACE_SOURCES.put(InterfaceID.TOB_CHESTS, "Theatre of Blood");
		INTERFACE_SOURCES.put(InterfaceID.TOA_CHESTS, "Tombs of Amascut");
		INTERFACE_SOURCES.put(InterfaceID.PMOON_REWARD, "Lunar Chest");
		INTERFACE_SOURCES.put(InterfaceID.COLOSSEUM_REWARD_CHEST_2, "Fortis Colosseum");
		INTERFACE_SOURCES.put(InterfaceID.TRAWLER_REWARD, "Fishing Trawler");
		INTERFACE_SOURCES.put(InterfaceID.FOSSIL_DRIFTNET, "Drift Net");
	}

	private final DropRateDisplayConfig config;
	private final DropRateDataStore dataStore;
	private final ItemManager itemManager;
	private final TextComponent textComponent = new TextComponent();

	/** Clue caskets share one interface for every tier; the plugin updates this on clue completion. */
	private volatile String clueCasketSource;

	@Inject
	RewardInterfaceOverlay(DropRateDisplayConfig config, DropRateDataStore dataStore, ItemManager itemManager)
	{
		this.config = config;
		this.dataStore = dataStore;
		this.itemManager = itemManager;

		int[] groups = new int[INTERFACE_SOURCES.size() + 1];
		int i = 0;
		for (int group : INTERFACE_SOURCES.keySet())
		{
			groups[i++] = group;
		}
		groups[i] = InterfaceID.TRAIL_REWARDSCREEN;
		showOnInterfaces(groups);
	}

	void setClueCasketSource(String source)
	{
		this.clueCasketSource = source;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showRewardInterfaceRates())
		{
			return;
		}

		int group = widgetItem.getWidget().getId() >>> 16;
		String source = group == InterfaceID.TRAIL_REWARDSCREEN ? clueCasketSource : INTERFACE_SOURCES.get(group);
		if (source == null)
		{
			return;
		}

		SourceDropTable table = dataStore.getSource(source);
		if (table == null)
		{
			return;
		}

		String itemName = itemManager.getItemComposition(itemId).getName();
		DropRateEntry entry = table.getDrop(itemName, widgetItem.getQuantity());
		if (entry == null
			|| !RateParser.shouldDisplay(entry.getRate(), config.minimumRarity(), config.showQualitativeRates(),
			config.showGuaranteedDrops()))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		String text = RateParser.format(entry.getRate(), config.rewardRateFormat());
		FontMetrics metrics = graphics.getFontMetrics();
		int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		int y = bounds.y + bounds.height;

		textComponent.setText(text);
		textComponent.setColor(RarityColor.colour(text, config));
		textComponent.setOutline(true);
		textComponent.setPosition(new Point(x, y));
		textComponent.render(graphics);
	}
}

package com.dropratedisplay;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Remembers which tile each item id spawned on during the current game tick.
 *
 * <p>{@link net.runelite.client.events.NpcLootReceived} names the NPC and the items but not where the
 * loot landed, and RuneLite's {@code LootManager} gathers a boss's loot from wherever it spawns — which
 * for many bosses (the Leviathan, the Wilderness trio, Vorkath, Nex, …) is under the player, several
 * tiles from the NPC's own tile. Because the loot's {@code ItemSpawned} events fire before
 * {@code NpcLootReceived} on the same tick, recording them here lets the plugin anchor each rate to the
 * real drop tile instead of the NPC's tile.
 *
 * <p>Only the current tick's spawns are kept: the map is cleared as soon as a spawn arrives on a later
 * tick, and {@link #tileFor} returns null unless queried on the same tick the spawn was recorded — so an
 * item already lying on the ground can never be matched to a later kill.
 */
class RecentSpawns
{
	private final Map<Integer, WorldPoint> tileByItem = new HashMap<>();
	private int tick = Integer.MIN_VALUE;

	/** Records that {@code itemId} spawned on {@code tile} during {@code currentTick}. */
	void record(int currentTick, int itemId, WorldPoint tile)
	{
		if (currentTick != tick)
		{
			tileByItem.clear();
			tick = currentTick;
		}
		tileByItem.put(itemId, tile);
	}

	/** The tile {@code itemId} spawned on this tick, or null if it did not spawn on {@code currentTick}. */
	WorldPoint tileFor(int currentTick, int itemId)
	{
		return currentTick == tick ? tileByItem.get(itemId) : null;
	}

	void clear()
	{
		tileByItem.clear();
		tick = Integer.MIN_VALUE;
	}
}

package com.dropratedisplay;

import java.util.HashMap;
import java.util.Map;

/**
 * Computes which items were added to a container between two snapshots.
 *
 * <p>Used to detect inventory-received loot (pickpockets, salvage, chest rewards): snapshot the
 * inventory when a loot trigger fires, then diff against the inventory after the container changes.
 */
public final class InventoryDiff
{
	private InventoryDiff()
	{
	}

	/**
	 * Returns item id &rarr; quantity added, i.e. the positive per-item deltas from {@code before} to
	 * {@code after}. Items whose count did not increase are omitted.
	 */
	public static Map<Integer, Integer> added(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Map<Integer, Integer> result = new HashMap<>();
		if (after == null)
		{
			return result;
		}

		for (Map.Entry<Integer, Integer> entry : after.entrySet())
		{
			int previous = before == null ? 0 : before.getOrDefault(entry.getKey(), 0);
			int delta = entry.getValue() - previous;
			if (delta > 0)
			{
				result.put(entry.getKey(), delta);
			}
		}
		return result;
	}
}
